from __future__ import annotations

from collections.abc import Iterable


def _parse(version: str) -> tuple[int, int, int, tuple[tuple[int, int | str], ...]]:
    """Parse a semantic version into its precedence-relevant components."""
    version, _, _build = version.partition('+')
    core, separator, prerelease = version.partition('-')
    major, minor, patch = (int(part) for part in core.split('.'))

    if separator:
        identifiers = tuple(
            (0, int(identifier)) if identifier.isdigit() else (1, identifier)
            for identifier in prerelease.split('.')
        )
    else:
        identifiers = ()

    return major, minor, patch, identifiers


def _precedence_key(version: str) -> tuple[int, int, int, int, tuple[tuple[int, int | str], ...]]:
    major, minor, patch, prerelease = _parse(version)
    # A release is greater than any pre-release of the same core version.
    return major, minor, patch, 0 if prerelease else 1, prerelease


def sort_versions(vs: Iterable[str]) -> list[str]:
    """Sort semantic version strings by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored, and versions with equal precedence retain their
    input order.
    """
    return sorted(vs, key=_precedence_key)
